  /**
   * @method
   * @name p2b#fetchMyTrades
   * @description fetch all trades made by the user, only the transaction
   * records in the past 3 month can be queried, the time between since and
   * params["until"] cannot be longer than 24 hours
   * @see
   * https://github.com/P2B-team/p2b-api-docs/blob/master/api-doc.md#deals-history-by-market
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for, default =
   * params["until"] - 86400000
   * @param {int} [limit] 1-100, default=50
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch orders for,
   * default = current timestamp or since + 86400000
   *
   * EXCHANGE SPECIFIC PARAMETERS
   * @param {int} [params.offset] 0-10000, default=0
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchMyTrades() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"));
                 params = this->omit(params, std::string("until"));
                 if (isTrue(isEqual(until, ccxt::any{}))) {
                   if (isTrue(isEqual(since, ccxt::any{}))) {
                     until = this->milliseconds();
                   } else {
                     until = add(since, 86400000);
                   }
                 }
                 if (isTrue(isEqual(since, ccxt::any{}))) {
                   since = subtract(until, 86400000);
                 }
                 if (isTrue(
                         isGreaterThan((subtract(until, since)), 86400000))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" fetchMyTrades () the time between "
                                       "since and params[\"until\"] cannot be "
                                       "greater than 24 hours"))));
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any sinceSec = this->parseToInt(divide(since, 1000));
                 ccxt::any untilSec = this->parseToInt(divide(until, 1000));
                 ccxt::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                     {std::string("startTime"), sinceSec},
                     {std::string("endTime"), untilSec},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response =
                     awaitValue(this->privatePostAccountMarketDealHistory(
                         this->extend(request, params)));
                 //
                 //    {
                 //        "success": true,
                 //        "errorCode": "",
                 //        "message": "",
                 //        "result": {
                 //            "total": 2,                                 //
                 //            Total records in the queried range "deals": [
                 //                {
                 //                    "deal_id": 7450617292,              //
                 //                    Deal id "deal_time": 1698506956.66224, //
                 //                    Deal execution time "deal_order_id":
                 //                    171955225751,      // Deal order id
                 //                    "opposite_order_id": 171955110512,  //
                 //                    Opposite order id "side": "sell", // Deal
                 //                    side "price": "0.05231", // Deal price
                 //                    "amount": "0.002",                  //
                 //                    Deal amount "deal": "0.00010462", //
                 //                    Total (price * amount) "deal_fee":
                 //                    "0.000000188316",       // Deal fee
                 //                    "role": "taker",                    //
                 //                    Role. Taker or maker "isSelfTrade": false
                 //                    // is self trade
                 //                },
                 //                ...
                 //            ]
                 //        }
                 //    }
                 //
                 ccxt::any result = this->safeValue(
                     response, std::string("result"), ccxt::dict{});
                 ccxt::any deals =
                     this->safeList(result, std::string("deals"), ccxt::list{});
                 return this->parseTrades(deals, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name p2b#fetchClosedOrders
   * @description fetches information on multiple closed orders made by the
   * user, the time between since and params["until"] cannot be longer than 24
   * hours
   * @see
   * https://github.com/P2B-team/p2b-api-docs/blob/master/api-doc.md#orders-history-by-market
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for, default =
   * params["until"] - 86400000
   * @param {int} [limit] 1-100, default=50
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch orders for,
   * default = current timestamp or since + 86400000
   *
   * EXCHANGE SPECIFIC PARAMETERS
   * @param {int} [params.offset] 0-10000, default=0
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any> fetchClosedOrders(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"));
                 params = this->omit(params, std::string("until"));
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 if (isTrue(isEqual(until, ccxt::any{}))) {
                   if (isTrue(isEqual(since, ccxt::any{}))) {
                     until = this->milliseconds();
                   } else {
                     until = add(since, 86400000);
                   }
                 }
                 if (isTrue(isEqual(since, ccxt::any{}))) {
                   since = subtract(until, 86400000);
                 }
                 if (isTrue(
                         isGreaterThan((subtract(until, since)), 86400000))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" fetchClosedOrders () the time between "
                                       "since and params[\"until\"] cannot be "
                                       "greater than 24 hours"))));
                 }
                 ccxt::any sinceSec = this->parseToInt(divide(since, 1000));
                 ccxt::any untilSec = this->parseToInt(divide(until, 1000));
                 ccxt::any request = ccxt::dict{
                     {std::string("startTime"), sinceSec},
                     {std::string("endTime"), untilSec},
                 };
                 if (isTrue(!isEqual(market, ccxt::any{}))) {
                   ::setValue(request, std::string("market"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response =
                     awaitValue(this->privatePostAccountOrderHistory(
                         this->extend(request, params)));
                 //
                 //    {
                 //        "success": true,
                 //        "errorCode": "",
                 //        "message": "",
                 //        "result": {
                 //            "LTC_USDT": [
                 //                {
                 //                    "id": 173985944395,
                 //                    "amount": "0.1",
                 //                    "price": "73",
                 //                    "type": "limit",
                 //                    "side": "sell",
                 //                    "ctime": 1699436194.390845,
                 //                    "ftime": 1699436194.390847,
                 //                    "market": "LTC_USDT",
                 //                    "takerFee": "0.002",
                 //                    "makerFee": "0.002",
                 //                    "dealFee": "0.01474",
                 //                    "dealStock": "0.1",
                 //                    "dealMoney": "7.37"
                 //                }
                 //            ]
                 //        }
                 //    }
                 //
                 ccxt::any result =
                     this->safeValue(response, std::string("result"));
                 ccxt::any orders = ccxt::list{};
                 ccxt::any keys = getObjectKeys(result);
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(keys));
                      postFixIncrement(i)) {
                   ccxt::any marketId = ::getValue(keys, i);
                   ccxt::any marketOrders = ::getValue(result, marketId);
                   ccxt::any parsedOrders =
                       this->parseOrders(marketOrders, market, since, limit);
                   orders = this->arrayConcat(orders, parsedOrders);
                 }
                 return orders;
               })
        .share();
  }

  ccxt::any parseOrder(ccxt::any order,
                       ccxt::any market = ccxt::any{}) override {
    //
    // cancelOrder, fetchOpenOrders, createOrder
    //
    //    {
    //        "orderId": 171906478744,
    //        "market": "ETH_BTC",
    //        "price": "0.04348",
    //        "side": "buy",
    //        "type": "limit",
    //        "timestamp": 1698484861.746517,
    //        "dealMoney": "0",
    //        "dealStock": "0",
    //        "amount": "0.0277",
    //        "takerFee": "0.002",
    //        "makerFee": "0.002",
    //        "left": "0.0277",
    //        "dealFee": "0"
    //    }
    //
    // fetchClosedOrders
    //
    //    {
    //        "id": 171366547790,           // Order id
    //        "amount": "0.00032",          // Original amount
    //        "price": "34293.92",          // Order price
    //        "type": "limit",              // Order type
    //        "side": "sell",               // Order side
    //        "ctime": 1698237533.497241,   // Order creation time
    //        "ftime": 1698237535.41196,    // Order fill time
    //        "market": "BTC_USDT",         // Market name
    //        "takerFee": "0.0018",         // Taker fee
    //        "makerFee": "0.0016",         // Market fee
    //        "dealFee": "0.01755848704",   // Deal fee
    //        "dealStock": "0.00032",       // Filled amount
    //        "dealMoney": "10.9740544"     // Filled total
    //    }
    //
    ccxt::any timestamp = this->safeIntegerProduct2(
        order, std::string("timestamp"), std::string("ctime"), 1000);
    ccxt::any marketId = this->safeString(order, std::string("market"));
    market = this->safeMarket(marketId, market);
    return this->safeOrder(
        ccxt::dict{
            {std::string("info"), order},
            {std::string("id"), this->safeString2(order, std::string("id"),
                                                  std::string("orderId"))},
            {std::string("clientOrderId"), ccxt::any{}},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"), ccxt::any{}},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("type"), this->safeString(order, std::string("type"))},
            {std::string("timeInForce"), ccxt::any{}},
            {std::string("postOnly"), ccxt::any{}},
            {std::string("side"), this->safeString(order, std::string("side"))},
            {std::string("price"),
             this->safeString(order, std::string("price"))},
            {std::string("triggerPrice"), ccxt::any{}},
            {std::string("amount"),
             this->safeString(order, std::string("amount"))},
            {std::string("cost"), ccxt::any{}},
            {std::string("average"), ccxt::any{}},
            {std::string("filled"),
             this->safeString(order, std::string("dealStock"))},
            {std::string("remaining"),
             this->safeString(order, std::string("left"))},
            {std::string("status"), ccxt::any{}},
            {std::string("fee"),
             ccxt::dict{
                 {std::string("currency"),
                  ::getValue(market, std::string("quote"))},
                 {std::string("cost"),
                  this->safeString(order, std::string("dealFee"))},
             }},
            {std::string("trades"), ccxt::any{}},
        },
        market);
  }

  ccxt::any sign(ccxt::any path, ccxt::any api = std::string("public"),
                 ccxt::any method = std::string("GET"),
                 ccxt::any params = ccxt::dict{},
                 ccxt::any headers = ccxt::any{},
                 ccxt::any body = ccxt::any{}) override {
    ccxt::any url =
        add(add(::getValue(::getValue(this->urls, std::string("api")), api),
                std::string("/")),
            this->implodeParams(path, params));
    params = this->omit(params, this->extractParams(path));
    if (isTrue(isEqual(method, std::string("GET")))) {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(params)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(params)));
      }
    }
    if (isTrue(isEqual(api, std::string("private")))) {
      ::setValue(params, std::string("request"),
                 add(std::string("/api/v2/"), path));
      ::setValue(params, std::string("nonce"), toString(this->nonce()));
      ccxt::any payload = this->stringToBase64(
          this->json(params)); // Body json encoded in base64
      headers = ccxt::dict{
          {std::string("Content-Type"), std::string("application/json")},
          {std::string("X-TXC-APIKEY"), this->apiKey},
          {std::string("X-TXC-PAYLOAD"), payload},
          {std::string("X-TXC-SIGNATURE"),
           this->hmac(this->encode(payload), this->encode(this->secret),
                      sha512)},
      };
      body = this->json(params);
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  ccxt::any handleErrors(ccxt::any code, ccxt::any reason, ccxt::any url,
                         ccxt::any method, ccxt::any headers, ccxt::any body,
                         ccxt::any response, ccxt::any requestHeaders,
                         ccxt::any requestBody) override {
    if (isTrue(isEqual(response, ccxt::any{}))) {
      return ccxt::any{};
    }
    //
    //     {"success":false,"errorCode":2021,"message":"Unknown
    //     market.","result":[]}
    //     {"success":false,"errorCode":1010,"message":"This action is
    //     unauthorized.","result":[]}
    //     {"success":true,"errorCode":"","message":"","result":{...},"cache_time":1787611797.535462,"current_time":1787611797.535973}
    //
    ccxt::any success = this->safeBool(response, std::string("success"), true);
    if (isTrue(!isEqual(success, true))) {
      ccxt::any errorCode =
          this->safeString(response, std::string("errorCode"));
      ccxt::any feedback = add(add(this->id, std::string(" ")), body);
      this->throwExactlyMatchedException(
          ::getValue(this->exceptions, std::string("exact")), errorCode,
          feedback);
      if (isTrue(isLessThan(code, 400))) {
        throw ExchangeError(toString(feedback));
      }
    }
    return ccxt::any{};
  }
